// Default Confluence URL → config key mapping (for resolving URLs in agent configs)
var CONFLUENCE_URL_MAP = {};
(function() {
    var conf = DEFAULTS.confluence;
    for (var key in conf) {
        if (conf.hasOwnProperty(key)) {
            CONFLUENCE_URL_MAP[conf[key]] = key;
