   return run.status || fallbackStatus || 'active';
}

function workflowRunId(run) {
   return run.id || run.databaseId || run.run_number || run.runNumber || '?';
}

function workflowRunUrl(run) {
   return run.html_url || run.htmlUrl || run.url || '';
}

